SourceCode.Declaration:
/// <summary>
/// Extension class
/// </summary>
[ExtensionOf(tableStr(UnitOfMeasureConversion))]
Public final class METUnitOfMeasureConversion_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC on update
    /// </summary>
    public void update()
    {
        boolean fieldUpdated = false;
        UnitOfMeasureConversion unitOfMeasureConversionOrig = this.orig();

        if(this.Factor          != unitOfMeasureConversionOrig.Factor
        || this.ToUnitOfMeasure != unitOfMeasureConversionOrig.ToUnitOfMeasure
        || this.FromUnitOfMeasure != unitOfMeasureConversionOrig.FromUnitOfMeasure)
        {
            fieldUpdated = true;
        }

        next update();

        if(fieldUpdated)
        {
            METPriceChangeEventProduct::metProcessTrackChange(InventTable::findByProduct(this.Product));
        }
    }
